#include <bits/stdc++.h>
using namespace std;
class Solution {public:long long maximumSum(vector<int>& nums){unordered_map<int,long long> sums;long long ans=0;for(int i=1;i<=(int)nums.size();++i){int x=i,key=1;for(int p=2;p*p<=x;++p){int parity=0;while(x%p==0){x/=p;parity^=1;}if(parity)key*=p;}if(x>1)key*=x;ans=max(ans,sums[key]+=nums[i-1]);}return ans;}};
